<?php
require_once __DIR__.'/../config/config.php';$user=require_employee_user();$pdo=db();$employee=employee_owner($pdo,$user);$q=$pdo->prepare('SELECT d.*,t.name type_name FROM employee_documents d JOIN document_types t ON t.id=d.document_type_id WHERE d.employee_id=? AND d.status="ACTIVE" ORDER BY d.created_at DESC');$q->execute([$employee['id']]);$documents=$q->fetchAll();audit('VIEW_DOCUMENTS','employee_documents',$employee['id']);$pageTitle='My documents';require __DIR__.'/../includes/header.php';?><div class="mb-7"><p class="text-sm text-slate-500">Documents available to your account</p><h1 class="font-display text-3xl font-bold mt-1">My documents</h1></div><section class="bg-white border rounded-xl p-6"><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="text-xs uppercase text-slate-400"><tr><th class="py-3">Title</th><th>Type</th><th>Issue date</th><th>Effective date</th><th>Status</th></tr></thead><tbody class="divide-y"><?php foreach($documents as $document):?><tr><td class="py-3 font-bold"><?=e($document['title'])?></td><td><?=e($document['type_name'])?></td><td><?=e($document['issue_date']??'—')?></td><td><?=e($document['effective_date']??'—')?></td><td><?=e($document['status'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$documents):?><p class="py-8 text-center text-slate-500">No documents are available.</p><?php endif;?></div></section><?php require __DIR__.'/../includes/footer.php';